import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`computer-opus`,inputUrlPlaceholder:`you@email.com`,heroTitle:`Orchestrate 20 AI models — not just one`,heroSubtitle:`Perplexity Computer orchestrates 20 AI models — GPT-5.5, Opus 4.8, Gemini 3.1 Pro, and more — spinning up specialized agents that route each task to the best model and deliver complete workflows automatically.`,heroOverlaySteps:[`Analyzing your task and breaking it into specialized steps`,`Selecting the optimal AI model for each subtask`,`Coordinating agents across models to execute your workflow`,`Complete deliverable assembled — ready to review`],generatingSteps:[`Breaking your project into discrete tasks for multi-model orchestration`,`Designing an agent to route each task to the best-fit AI model`,`Configuring specialized agents across 20 models — including Opus 4.8, GPT-5.5, Gemini 3.1 Pro, and more`,`Setting up coordinated execution so every output meets your standards`],featureSectionTitle:`From one prompt to twenty models working for you`,featureCardTitles:[`Connects to your entire stack`,`Outputs you can ship`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, Slack, GitHub, Airtable — Computer pulls data from your tools and pushes results back where you need them.`,`Research reports. Code implementations. Marketing copy. Data analysis. Strategic plans. Complete deliverables — not half-finished drafts from a single model.`],capabilitySectionTitle:`Your AI team, on autopilot`,capabilitySectionSubtitle:`Describe your task, step away, get back a finished deliverable from 20 models working together.`,capabilityCards:[{title:`Model Orchestration`,description:`Computer can analyze your task, decompose it into subtasks, and route each one to the AI model with the strongest performance for that specific job.`},{title:`Multi-Step Workflows`,description:`Computer can chain research, analysis, writing, and coding into a single workflow — each step handled by a specialized agent tuned for the task.`},{title:`Real-Time Research`,description:`Computer can search the live web, pull current data, and ground every output in real sources — not stale training data from a single model.`},{title:`Connect Your Tools`,description:`Computer can integrate with Google Sheets, Google Drive, Notion, Slack, GitHub, and Airtable — build workflows across your entire productivity stack.`},{title:`Learns Your Needs`,description:`Computer can remember your preferences, past workflows, and quality standards — so every new task builds on what it already knows about your work.`},{title:`Monitor & Alert`,description:`Computer can watch for changes in data, competitor activity, or project status — and alert you the moment something needs your attention.`}]});export{t as default};
